package com.investfusion;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import jakarta.servlet.http.HttpSession;
import jakarta.validation.Valid;
import java.util.*;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/api")
@CrossOrigin(origins ="*", allowCredentials = "true")
public class ApiController {
    private final HoldingRepository repository; private final AppUserRepository users; private final CasParserService parser; private final MarketPriceService market;
    public ApiController(HoldingRepository repository, AppUserRepository users, CasParserService parser, MarketPriceService market) { this.repository=repository; this.users=users; this.parser=parser; this.market=market; }
    @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","ok","application","InvestFusion AI","port",9000);}
    private Long userId(HttpSession session){Object id=session.getAttribute("userId");return id instanceof Long?(Long)id:null;}
    private ResponseEntity<Map<String,String>> unauthorized(){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("message","Please log in to access your portfolio."));}
    @GetMapping("/holdings") public ResponseEntity<?> all(HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();return ResponseEntity.ok(repository.findAllByOwnerId(uid));}
    @PostMapping("/holdings") public ResponseEntity<?> add(@Valid @RequestBody Holding h,HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();Optional<AppUser> user=users.findById(uid);if(user.isEmpty())return unauthorized();h.setId(null);h.setOwner(user.get());return ResponseEntity.ok(repository.save(h));}
    @PutMapping("/holdings/{id}") public ResponseEntity<?> update(@PathVariable Long id,@Valid @RequestBody Holding input,HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();Optional<Holding> found=repository.findByIdAndOwnerId(id,uid);if(found.isEmpty())return ResponseEntity.notFound().build();Holding h=found.get();h.setName(input.getName());h.setSymbol(input.getSymbol());h.setIsin(input.getIsin());h.setAssetType(input.getAssetType());h.setQuantity(input.getQuantity());h.setAverageCost(input.getAverageCost());h.setCurrentPrice(input.getCurrentPrice());h.setStatementValue(input.getStatementValue());h.setNotes(input.getNotes());return ResponseEntity.ok(repository.save(h));}
    @DeleteMapping("/holdings/{id}") public ResponseEntity<?> delete(@PathVariable Long id,HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();Optional<Holding> h=repository.findByIdAndOwnerId(id,uid);if(h.isEmpty())return ResponseEntity.notFound().build();repository.delete(h.get());return ResponseEntity.noContent().build();}
    @PostMapping("/cas/upload") public ResponseEntity<?> upload(@RequestParam("file") MultipartFile file,HttpSession session) throws Exception {if(userId(session)==null)return unauthorized();if(file.isEmpty())return ResponseEntity.badRequest().body(Map.of("message","Please select a PDF file."));if(file.getSize()>15*1024*1024)return ResponseEntity.badRequest().body(Map.of("message","PDF must be smaller than 15 MB."));return ResponseEntity.ok(Map.of("filename",file.getOriginalFilename()==null?"statement.pdf":file.getOriginalFilename(),"holdings",parser.parse(file.getBytes())));}
    @PostMapping("/cas/import") public ResponseEntity<?> importParsed(@RequestBody List<Holding> holdings,HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();Optional<AppUser> user=users.findById(uid);if(user.isEmpty())return unauthorized();List<Holding> clean=holdings.stream().filter(h->h.getName()!=null&&!h.getName().isBlank()&&h.getQuantity()>=0).peek(h->{h.setId(null);h.setOwner(user.get());}).collect(Collectors.toList());return ResponseEntity.ok(repository.saveAll(clean));}
    @PostMapping("/market/refresh") public ResponseEntity<?> refresh(HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();List<Holding> hs=repository.findAllByOwnerId(uid);int updated=0;for(Holding h:hs){double price=market.fetch(h.getSymbol());if(price>0){h.setCurrentPrice(price);repository.save(h);updated++;}}return ResponseEntity.ok(Map.of("updated",updated,"total",hs.size(),"message",updated==0?"No external quotes were available; saved prices were kept.":"Price refresh complete (best-effort external quotes)."));}
    @GetMapping("/insights") public ResponseEntity<?> insights(HttpSession session){Long uid=userId(session);if(uid==null)return unauthorized();List<Holding> hs=repository.findAllByOwnerId(uid);double invested=hs.stream().mapToDouble(Holding::getInvestedValue).sum();double value=hs.stream().mapToDouble(Holding::getMarketValue).sum();double pl=value-invested;List<String> tips=new ArrayList<>();if(hs.size()<5)tips.add("Your portfolio has a small number of holdings. Review concentration and diversification.");long funds=hs.stream().filter(h->"MUTUAL_FUND".equalsIgnoreCase(h.getAssetType())).count();if(funds==0)tips.add("There are no mutual-fund entries in this portfolio. Consider whether your allocation matches your goals.");if(invested>0&&Math.abs(pl/invested)>0.15)tips.add("Portfolio P&L has moved more than 15% from invested value. Recheck your time horizon and risk tolerance.");if(tips.isEmpty())tips.add("Keep tracking allocation, costs, and long-term goals. Avoid making decisions from short-term price moves alone.");return ResponseEntity.ok(Map.of("investedValue",invested,"marketValue",value,"profitLoss",pl,"profitLossPercent",invested==0?0:pl/invested*100,"tips",tips,"disclaimer","Educational insights only; not personalized financial advice."));}
}
